Your expense tracker is below: add what you spend, set a monthly budget, and see the total and a split by category. It resets when you close the page, so note down the totals you want to keep.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:16px;background:#f6f7f9;color:#1f2430}
h1{font-size:20px;margin:0 0 12px}
.card{background:#fff;border-radius:12px;padding:14px;margin-bottom:12px;box-shadow:0 1px 3px rgba(0,0,0,.08)}
.row{display:flex;gap:8px;flex-wrap:wrap}
input,select{padding:8px;border:1px solid #ccd;border-radius:8px;font-size:14px;flex:1;min-width:110px}
button{padding:8px 14px;border:0;border-radius:8px;background:#2f6fed;color:#fff;font-size:14px;cursor:pointer}
button.x{background:#e5e7eb;color:#444;padding:4px 10px}
.stats{display:flex;gap:12px;flex-wrap:wrap}
.stat{flex:1;min-width:120px}
.stat b{display:block;font-size:20px}
.stat span{font-size:12px;color:#667}
.bar{height:10px;background:#e5e7eb;border-radius:6px;overflow:hidden;margin:4px 0 10px}
.bar i{display:block;height:100%;background:#2f6fed}
.over{color:#c62828}
.item{display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-bottom:1px solid #eee;font-size:14px}
.item small{color:#778;display:block}
.empty{color:#889;font-size:14px}
</style>
</head>
<body>
<h1>Expenses for <span id="month"></span></h1>

<div class="card">
  <div class="stats">
    <div class="stat"><span>Spent</span><b id="spent">₹0</b></div>
    <div class="stat"><span>Budget</span><b id="budgetShow">₹0</b></div>
    <div class="stat"><span>Left</span><b id="left">₹0</b></div>
  </div>
  <div class="bar" style="margin-top:10px"><i id="usedBar" style="width:0"></i></div>
  <div class="row"><input id="budget" type="number" min="0" placeholder="Monthly budget (₹)"><button id="setBudget">Set budget</button></div>
</div>

<div class="card">
  <div class="row">
    <input id="name" placeholder="What was it for?">
    <input id="amt" type="number" min="0" placeholder="Amount (₹)">
  </div>
  <div class="row" style="margin-top:8px">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option>
      <option>Shopping</option><option>Health</option><option>Fun</option><option>Other</option>
    </select>
    <input id="date" type="date">
    <button id="add">Add</button>
  </div>
</div>

<div class="card"><b>By category</b><div id="cats" style="margin-top:8px"></div></div>
<div class="card"><b>All expenses</b><div id="list" style="margin-top:4px"></div></div>

<script>
var items=[],budget=0;
var $=function(i){return document.getElementById(i)};
var inr=function(n){return "₹"+Math.round(n).toLocaleString("en-IN")};
var today=new Date();
$("date").value=today.toISOString().slice(0,10);
$("month").textContent=today.toLocaleString("en-IN",{month:"long",year:"numeric"});

function render(){
  var total=0,by={};
  items.forEach(function(e){total+=e.amt;by[e.cat]=(by[e.cat]||0)+e.amt});
  $("spent").textContent=inr(total);
  $("budgetShow").textContent=inr(budget);
  var left=budget-total;
  var l=$("left");
  l.textContent=(left<0?"-":"")+inr(Math.abs(left));
  l.className=left<0?"over":"";
  $("usedBar").style.width=(budget>0?Math.min(100,total/budget*100):0)+"%";
  $("usedBar").style.background=left<0?"#c62828":"#2f6fed";

  var c=$("cats");c.innerHTML="";
  var keys=Object.keys(by).sort(function(a,b){return by[b]-by[a]});
  if(!keys.length)c.innerHTML='<div class="empty">Nothing added yet.</div>';
  keys.forEach(function(k){
    var d=document.createElement("div");
    d.innerHTML='<div style="display:flex;justify-content:space-between;font-size:14px"><span>'+k+'</span><span>'+inr(by[k])+'</span></div><div class="bar"><i style="width:'+(by[k]/total*100)+'%"></i></div>';
    c.appendChild(d);
  });

  var list=$("list");list.innerHTML="";
  if(!items.length)list.innerHTML='<div class="empty">Your expenses will show here.</div>';
  items.slice().reverse().forEach(function(e){
    var d=document.createElement("div");d.className="item";
    var left=document.createElement("div");
    var t=document.createElement("span");t.textContent=e.name;
    var s=document.createElement("small");s.textContent=e.cat+" · "+e.date;
    left.appendChild(t);left.appendChild(s);
    var right=document.createElement("div");
    right.appendChild(document.createTextNode(inr(e.amt)+" "));
    var b=document.createElement("button");b.className="x";b.textContent="Delete";
    b.onclick=function(){items.splice(items.indexOf(e),1);render()};
    right.appendChild(b);
    d.appendChild(left);d.appendChild(right);list.appendChild(d);
  });
}

$("add").onclick=function(){
  var a=parseFloat($("amt").value);
  if(!(a>0))return;
  items.push({name:$("name").value.trim()||$("cat").value,amt:a,cat:$("cat").value,date:$("date").value});
  $("name").value="";$("amt").value="";
  render();
};
$("setBudget").onclick=function(){
  var b=parseFloat($("budget").value);
  budget=b>0?b:0;render();
};
render();
</script>
</body>
</html>
```

Here's your water tracker: tap a glass to log it, and it fills up toward your goal of 8 glasses.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: Segoe UI, sans-serif; text-align: center; padding: 24px; margin: 0; }
  h1 { font-size: 20px; margin: 0 0 4px; }
  #count { font-size: 40px; font-weight: 600; margin: 12px 0 4px; }
  #msg { color: #555; margin-bottom: 16px; min-height: 20px; }
  #bar { width: 100%; max-width: 320px; height: 12px; background: #dde8f0; border-radius: 6px; margin: 0 auto 20px; overflow: hidden; }
  #fill { height: 100%; width: 0; background: #2b8fd6; transition: width .3s; }
  #glasses { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; max-width: 320px; margin: 0 auto 20px; }
  .g { width: 56px; height: 72px; border: 2px solid #2b8fd6; border-radius: 4px 4px 12px 12px; background: #fff; cursor: pointer; padding: 0; }
  .g.on { background: #2b8fd6; }
  .ctl button { font-size: 16px; padding: 8px 18px; margin: 0 6px; border-radius: 8px; border: 1px solid #2b8fd6; background: #fff; cursor: pointer; }
  .ctl button.p { background: #2b8fd6; color: #fff; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div id="count">0 / 8</div>
  <div id="msg"></div>
  <div id="bar"><div id="fill"></div></div>
  <div id="glasses"></div>
  <div class="ctl">
    <button type="button" id="minus">- Glass</button>
    <button type="button" id="plus" class="p">+ Glass</button>
    <button type="button" id="reset">Reset</button>
  </div>
<script>
  var GOAL = 8;
  var key = "water-" + new Date().toISOString().slice(0, 10);
  var n = 0;
  try { n = parseInt(localStorage.getItem(key), 10) || 0; } catch (e) {}

  function save() { try { localStorage.setItem(key, String(n)); } catch (e) {} }

  function draw() {
    document.getElementById("count").textContent = n + " / " + GOAL;
    document.getElementById("fill").style.width = Math.min(100, n / GOAL * 100) + "%";
    document.getElementById("msg").textContent =
      n >= GOAL ? "Goal reached. Well done!" : (GOAL - n) + " more to go";
    var box = document.getElementById("glasses");
    box.innerHTML = "";
    for (var i = 0; i < GOAL; i++) {
      var b = document.createElement("button");
      b.type = "button";
      b.className = "g" + (i < n ? " on" : "");
      b.setAttribute("aria-label", "Glass " + (i + 1));
      (function (k) {
        b.onclick = function () { n = (n === k + 1) ? k : k + 1; save(); draw(); };
      })(i);
      box.appendChild(b);
    }
  }

  document.getElementById("plus").onclick = function () { n++; save(); draw(); };
  document.getElementById("minus").onclick = function () { if (n > 0) n--; save(); draw(); };
  document.getElementById("reset").onclick = function () { n = 0; save(); draw(); };
  draw();
</script>
</body>
</html>
```

It starts fresh each day. If your app doesn't allow saving, the count resets when you close it.
